type Command interface{ Execute() }

type insertText struct { doc *Document; pos int; text string }
func (c insertText) Execute() { c.doc.Insert(c.pos, c.text) }

type Invoker struct{ history []Command }
func (in *Invoker) Do(c Command) { c.Execute(); in.history = append(in.history, c) }

